-- Correct live certification claims in producer/wine content.
-- Idempotent: each UPDATE matches id (or producer name) + current before-value.
-- Does NOT apply itself to production on merge; run via normal migration process.
--
-- Overlap with open PR #164 (migrations 268/269 — verified-URL schema + seed, UI labels):
--   * Ugo Lestelle: #164 leaves certification_verified_url NULL (Agence Bio ARRETEE) and
--     softens the organic_certified chip to "according to the producer"; this migration
--     only removes "certified organic" / "ekologiskt certifierat" from bio_long prose.
--     Does not change producers.certification or wines.farming for Ugo.
--   * La Marotte: #164 does not touch La Marotte (certification = natural, no seed URL).
--     This migration rephrases unverifiable "Ecocert-certified BIO" in bio_long.
--   * Pierre et l'Étoile: #164 seeds Ecocert URL only; does not change certification year
--     in copy. This migration corrects 2020 → 2017 for organic certification year claims
--     (sulphite-since-2020 phrasing left intact).
--   * Mas Des Mesures / Peira Levada: #164 seeds organic registry URLs and softens the
--     producer-level biodynamic chip (no Demeter/Biodyvin proof). This migration clears
--     wines.farming = 'biodynamic_certified' only (wine-level claim). Producer certification
--     stays biodynamic_certified for #164's according-to-producer label.
--     wines.farming is unconstrained text; live distinct values and
--     CATALOG_CERTIFICATION_VALUES / shop filters are only
--     organic_certified | biodynamic_certified | natural | sustainable | conventional —
--     no uncertified 'biodynamic' value exists, so farming is set to NULL (not invented).

-- ---------------------------------------------------------------------------
-- 1) Ugo Lestelle — remove ended organic certification claim from bio_long
--    Soften to according-to-producer (same phrasing family as La Marotte).
-- ---------------------------------------------------------------------------
UPDATE public.producers
SET bio_long = $j${"en": "Ugo Lestelle has worked in the vineyard since he was thirteen. He grew up in Lyon with family near Sète, and bought 2.5 hectares in Saint-Chinian at the age of 24. The first vintage was made in a garage in 2015, around 3,000 bottles. Success came quickly and the estate grew. Today it is twelve hectares, and that is where he wants it to stay — he does everything himself.\n\nThe vines sit at 250–350 metres around Saint-Chinian and Assignan, on schist and clay-limestone, organic (according to the producer). He ploughs four times a year to fifteen centimetres, leaves some grass and sows cover crops. Horses on the schist parcels, a tracked tractor on the clay-limestone. Hand harvest in 20-kilo crates, with eight days between the schist and the clay to catch the right ripeness.\n\nThe cellar in Pardailhan lies at 563 metres and four metres underground, giving constant coolness. Reds ferment whole-cluster with carbonic maceration on indigenous yeasts at 24–25°C. Whites are pressed directly, whole bunches. Ageing takes place in used 500-litre Burgundy barrels sourced from Clos de Tart in Burgundy and Château des Jacques in Beaujolais — never new oak, since the barrel is there for micro-oxygenation, not for flavour. No additives beyond at most 2 g/hl of sulphur at bottling.", "sv": "Ugo Lestelle har arbetat i vingården sedan han var tretton. Han kommer från Lyon med släkt i trakten kring Sète, och köpte vid 24 års ålder 2,5 hektar i Saint-Chinian. Första årgången gjordes 2015 i ett garage, omkring 3 000 flaskor. Framgången kom snabbt och arealen växte. Idag är det tolv hektar, och där vill han stanna — han sköter allt själv.\n\nVingårdarna ligger på 250–350 meters höjd kring Saint-Chinian och Assignan, på skiffer och lerkalk, ekologiskt (enligt producenten). Han plöjer fyra gånger om året till femton centimeters djup, lämnar en del gräs och sår gröngödsling. Hästen används på skifferparcellerna, chenillard på lerkalken. Handskörd i 20-kilos lådor, med åtta dagars förskjutning mellan skiffer och lera för att träffa rätt mognad.\n\nKällaren ligger i Pardailhan på 563 meters höjd och fyra meter under mark, vilket ger konstant svalka. De röda jäser med hela klasar och kolsyremaceration på egna jästsvampar vid 24–25 grader. De vita pressas direkt i hela klasar. Elevage sker i begagnade burgundiska fat på 500 liter som han hämtar från Clos de Tart i Bourgogne och Château des Jacques i Beaujolais — aldrig nya fat, eftersom fatet bara ska ge mikrooxidation och inte prägla vinet. Inga tillsatser utöver på sin höjd 2 g/hl svavel vid buteljering."}$j$::jsonb
WHERE id = 'a15c0f0d-e917-4c08-8981-67fb202948db'
  AND (
    -- live prod (certified claim)
    bio_long = $j${"en": "Ugo Lestelle has worked in the vineyard since he was thirteen. He grew up in Lyon with family near Sète, and bought 2.5 hectares in Saint-Chinian at the age of 24. The first vintage was made in a garage in 2015, around 3,000 bottles. Success came quickly and the estate grew. Today it is twelve hectares, and that is where he wants it to stay — he does everything himself.\n\nThe vines sit at 250–350 metres around Saint-Chinian and Assignan, on schist and clay-limestone, certified organic. He ploughs four times a year to fifteen centimetres, leaves some grass and sows cover crops. Horses on the schist parcels, a tracked tractor on the clay-limestone. Hand harvest in 20-kilo crates, with eight days between the schist and the clay to catch the right ripeness.\n\nThe cellar in Pardailhan lies at 563 metres and four metres underground, giving constant coolness. Reds ferment whole-cluster with carbonic maceration on indigenous yeasts at 24–25°C. Whites are pressed directly, whole bunches. Ageing takes place in used 500-litre Burgundy barrels sourced from Clos de Tart in Burgundy and Château des Jacques in Beaujolais — never new oak, since the barrel is there for micro-oxygenation, not for flavour. No additives beyond at most 2 g/hl of sulphur at bottling.", "sv": "Ugo Lestelle har arbetat i vingården sedan han var tretton. Han kommer från Lyon med släkt i trakten kring Sète, och köpte vid 24 års ålder 2,5 hektar i Saint-Chinian. Första årgången gjordes 2015 i ett garage, omkring 3 000 flaskor. Framgången kom snabbt och arealen växte. Idag är det tolv hektar, och där vill han stanna — han sköter allt själv.\n\nVingårdarna ligger på 250–350 meters höjd kring Saint-Chinian och Assignan, på skiffer och lerkalk, ekologiskt certifierat. Han plöjer fyra gånger om året till femton centimeters djup, lämnar en del gräs och sår gröngödsling. Hästen används på skifferparcellerna, chenillard på lerkalken. Handskörd i 20-kilos lådor, med åtta dagars förskjutning mellan skiffer och lera för att träffa rätt mognad.\n\nKällaren ligger i Pardailhan på 563 meters höjd och fyra meter under mark, vilket ger konstant svalka. De röda jäser med hela klasar och kolsyremaceration på egna jästsvampar vid 24–25 grader. De vita pressas direkt i hela klasar. Elevage sker i begagnade burgundiska fat på 500 liter som han hämtar från Clos de Tart i Bourgogne och Château des Jacques i Beaujolais — aldrig nya fat, eftersom fatet bara ska ge mikrooxidation och inte prägla vinet. Inga tillsatser utöver på sin höjd 2 g/hl svavel vid buteljering."}$j$::jsonb
    -- prior PR revision used plain organic/ekologiskt
    OR bio_long = $j${"en": "Ugo Lestelle has worked in the vineyard since he was thirteen. He grew up in Lyon with family near Sète, and bought 2.5 hectares in Saint-Chinian at the age of 24. The first vintage was made in a garage in 2015, around 3,000 bottles. Success came quickly and the estate grew. Today it is twelve hectares, and that is where he wants it to stay — he does everything himself.\n\nThe vines sit at 250–350 metres around Saint-Chinian and Assignan, on schist and clay-limestone, organic. He ploughs four times a year to fifteen centimetres, leaves some grass and sows cover crops. Horses on the schist parcels, a tracked tractor on the clay-limestone. Hand harvest in 20-kilo crates, with eight days between the schist and the clay to catch the right ripeness.\n\nThe cellar in Pardailhan lies at 563 metres and four metres underground, giving constant coolness. Reds ferment whole-cluster with carbonic maceration on indigenous yeasts at 24–25°C. Whites are pressed directly, whole bunches. Ageing takes place in used 500-litre Burgundy barrels sourced from Clos de Tart in Burgundy and Château des Jacques in Beaujolais — never new oak, since the barrel is there for micro-oxygenation, not for flavour. No additives beyond at most 2 g/hl of sulphur at bottling.", "sv": "Ugo Lestelle har arbetat i vingården sedan han var tretton. Han kommer från Lyon med släkt i trakten kring Sète, och köpte vid 24 års ålder 2,5 hektar i Saint-Chinian. Första årgången gjordes 2015 i ett garage, omkring 3 000 flaskor. Framgången kom snabbt och arealen växte. Idag är det tolv hektar, och där vill han stanna — han sköter allt själv.\n\nVingårdarna ligger på 250–350 meters höjd kring Saint-Chinian och Assignan, på skiffer och lerkalk, ekologiskt. Han plöjer fyra gånger om året till femton centimeters djup, lämnar en del gräs och sår gröngödsling. Hästen används på skifferparcellerna, chenillard på lerkalken. Handskörd i 20-kilos lådor, med åtta dagars förskjutning mellan skiffer och lera för att träffa rätt mognad.\n\nKällaren ligger i Pardailhan på 563 meters höjd och fyra meter under mark, vilket ger konstant svalka. De röda jäser med hela klasar och kolsyremaceration på egna jästsvampar vid 24–25 grader. De vita pressas direkt i hela klasar. Elevage sker i begagnade burgundiska fat på 500 liter som han hämtar från Clos de Tart i Bourgogne och Château des Jacques i Beaujolais — aldrig nya fat, eftersom fatet bara ska ge mikrooxidation och inte prägla vinet. Inga tillsatser utöver på sin höjd 2 g/hl svavel vid buteljering."}$j$::jsonb
  );

-- ---------------------------------------------------------------------------
-- 2) La Marotte — unverifiable Ecocert-certified BIO → according to the producer
--    EN bio_long had the Ecocert claim; SV lacked it, so SV gains the soft phrasing.
-- ---------------------------------------------------------------------------
UPDATE public.producers
SET bio_long = $j${"en": "La Marotte is situated in and around the village of Clairac, part of La Tour sur Orb, in the north of the Hérault département. Julie Thelen and Xavier Auboux farm some six hectares of vines that are organic (according to the producer).\n\nTwo-thirds of the vines are old and head-pruned — the gobelet method — on mostly mixed plots: Carignan Blanc, Carignan Noir, Cinsault, Oeillade, Ugni Blanc, Aramon, Terret (all 3 colours), Grenache (all 3 colours), Vermentino, Mourvèdre, Morastel, Alicante, Clairette, Grand Noir de la Calmette and more. One-third are younger, trellised vines pruned using the Cordon de Royat or Guyot method.\n\nThe harvesting is done manually. The grapes are pressed slowly and gently in a vertical hydraulic press dating from the 1930s. The wine is fermented and aged in stainless-steel or glass-fibre vats. Racking and bottling is done by gravity. Vinification occurs without any input whatsoever — no added sulphites, yeasts, clarification agents or enzymes. The wine is not filtered.\n\nGrapes, grapes and only grapes go into their bottles — except lashings of love.", "sv": "La Marotte ligger i Clairac vid foten av La Tour sur Orb i norra Hérault. Det är Julie Thelen och Xavier Auboux som driver domänet — ett par med rötter i kökskulturen som hamnade i vingården av kärlek till råvaran snarare än tradition. De odlar ekologiskt (enligt producenten).\n\nFilosofin är enkel: manuell skörd, inga tillsatser, inga tillsatta sulfiter, ingen intervention i källaren. Vinerna görs av det som finns på egna parceller plus raisin köpt från grannar i biodynamisk eller ekologisk odling. Varje cuvée är ett avtryck av ett specifikt år, en specifik parcell eller en känsla — inte en formel som upprepas.\n\nSortimentet är varierat och föränderligt. Micocoulier, Bienvenu.E.S, Résiste, La Plage, Vivace — namnen berättar mer om platsen och stunden än om druvsort eller stil. Produktionen är liten, tillgängligheten begränsad."}$j$::jsonb
WHERE id = '1d788c78-4b34-471e-903d-0c8a2700cb5a'
  AND bio_long = $j${"en": "La Marotte is situated in and around the village of Clairac, part of La Tour sur Orb, in the north of the Hérault département. Julie Thelen and Xavier Auboux farm some six hectares of organic vines, Ecocert-certified BIO.\n\nTwo-thirds of the vines are old and head-pruned — the gobelet method — on mostly mixed plots: Carignan Blanc, Carignan Noir, Cinsault, Oeillade, Ugni Blanc, Aramon, Terret (all 3 colours), Grenache (all 3 colours), Vermentino, Mourvèdre, Morastel, Alicante, Clairette, Grand Noir de la Calmette and more. One-third are younger, trellised vines pruned using the Cordon de Royat or Guyot method.\n\nThe harvesting is done manually. The grapes are pressed slowly and gently in a vertical hydraulic press dating from the 1930s. The wine is fermented and aged in stainless-steel or glass-fibre vats. Racking and bottling is done by gravity. Vinification occurs without any input whatsoever — no added sulphites, yeasts, clarification agents or enzymes. The wine is not filtered.\n\nGrapes, grapes and only grapes go into their bottles — except lashings of love.", "sv": "La Marotte ligger i Clairac vid foten av La Tour sur Orb i norra Hérault. Det är Julie Thelen och Xavier Auboux som driver domänet — ett par med rötter i kökskulturen som hamnade i vingården av kärlek till råvaran snarare än tradition.\n\nFilosofin är enkel: manuell skörd, inga tillsatser, inga tillsatta sulfiter, ingen intervention i källaren. Vinerna görs av det som finns på egna parceller plus raisin köpt från grannar i biodynamisk eller ekologisk odling. Varje cuvée är ett avtryck av ett specifikt år, en specifik parcell eller en känsla — inte en formel som upprepas.\n\nSortimentet är varierat och föränderligt. Micocoulier, Bienvenu.E.S, Résiste, La Plage, Vivace — namnen berättar mer om platsen och stunden än om druvsort eller stil. Produktionen är liten, tillgängligheten begränsad."}$j$::jsonb;

-- ---------------------------------------------------------------------------
-- 3) Pierre et l'Étoile — organic certification year 2020 → 2017 (registry)
--    Leave "no added sulphites since 2020" / "inga tillsatta sulfiter sedan 2020" unchanged.
-- ---------------------------------------------------------------------------
UPDATE public.producers
SET short_description = $j${"en": "Pierre Regnault founded Pierre et l'Étoile in 2017 in Assignan, Hérault, after years in vineyards and cellars in the Gard. 4.5 hectares across seven parcels on clay-limestone at 270 metres altitude. Organic certification since 2017. Indigenous yeasts, no additives, no added sulphites since 2020. The estate name is a dedication to his partner Estelle.", "sv": "Pierre Regnault grundade Pierre et l'Étoile 2017 i Assignan i Hérault efter år i vingårdar och källare i Gard. 4,5 hektar på sju parceller på argilo-calcaire vid 270 meters höjd. Ekologisk certifiering sedan 2017. Naturliga jästsvampar, inga tillsatser, inga tillsatta sulfiter sedan 2020. Domännamnet är en hälsning till hans partner Estelle."}$j$::jsonb
WHERE id = '2aa11a2c-8a09-4e08-b249-92927041bd7a'
  AND short_description = $j${"en": "Pierre Regnault founded Pierre et l'Étoile in 2017 in Assignan, Hérault, after years in vineyards and cellars in the Gard. 4.5 hectares across seven parcels on clay-limestone at 270 metres altitude. Organic certification since 2020. Indigenous yeasts, no additives, no added sulphites since 2020. The estate name is a dedication to his partner Estelle.", "sv": "Pierre Regnault grundade Pierre et l'Étoile 2017 i Assignan i Hérault efter år i vingårdar och källare i Gard. 4,5 hektar på sju parceller på argilo-calcaire vid 270 meters höjd. Ekologisk certifiering sedan 2020. Naturliga jästsvampar, inga tillsatser, inga tillsatta sulfiter sedan 2020. Domännamnet är en hälsning till hans partner Estelle."}$j$::jsonb;

UPDATE public.producers
SET bio_long = $j${"en": "Pierre Regnault founded Pierre et l'Étoile in 2017 in Assignan in northern Hérault, after years of hands-on experience in vineyards and cellars in the Gard. He brought those lessons with him and settled on 4.5 hectares spread across seven parcels in the Haute Vallée de l'Orb area.\n\nThe vineyard sits on clay-limestone at 270 metres altitude — a position that gives freshness and minerality. Organic certification was achieved in 2017. Pierre stopped adding sulphites entirely in 2020.\n\nThe estate name is a dedication to his partner Estelle — 'l'Étoile' is her name, a star built into the project's identity. Indigenous yeasts, no additives, minimal intervention in the cellar.", "sv": "Pierre Regnault grundade Pierre et l'Étoile 2017 i Assignan i norra Hérault efter år av praktisk erfarenhet i vingårdar och källare i Gard. Han tog med sig lärdomar från regionen och slog sig ned på 4,5 hektar fördelade på sju parceller i Haute Vallée de l'Orb-området.\n\nVingården ligger på argilo-calcaire vid 270 meters höjd — ett läge som ger friskhet och mineralitet. Ekologisk certifiering uppnåddes 2017. Pierre slutade tillsätta sulfiter helt 2020.\n\nDomännamnet är en hälsning till hans partner Estelle — 'l'Étoile' är hennes namn, en stjärna inbyggd i projektets identitet. Naturliga jästsvampar, inga tillsatser, minimal intervention i källaren."}$j$::jsonb
WHERE id = '2aa11a2c-8a09-4e08-b249-92927041bd7a'
  AND bio_long = $j${"en": "Pierre Regnault founded Pierre et l'Étoile in 2017 in Assignan in northern Hérault, after years of hands-on experience in vineyards and cellars in the Gard. He brought those lessons with him and settled on 4.5 hectares spread across seven parcels in the Haute Vallée de l'Orb area.\n\nThe vineyard sits on clay-limestone at 270 metres altitude — a position that gives freshness and minerality. Organic certification was achieved in 2020, the same year Pierre stopped adding sulphites entirely.\n\nThe estate name is a dedication to his partner Estelle — 'l'Étoile' is her name, a star built into the project's identity. Indigenous yeasts, no additives, minimal intervention in the cellar.", "sv": "Pierre Regnault grundade Pierre et l'Étoile 2017 i Assignan i norra Hérault efter år av praktisk erfarenhet i vingårdar och källare i Gard. Han tog med sig lärdomar från regionen och slog sig ned på 4,5 hektar fördelade på sju parceller i Haute Vallée de l'Orb-området.\n\nVingården ligger på argilo-calcaire vid 270 meters höjd — ett läge som ger friskhet och mineralitet. Ekologisk certifiering uppnåddes 2020, samma år som Pierre slutade tillsätta sulfiter helt.\n\nDomännamnet är en hälsning till hans partner Estelle — 'l'Étoile' är hennes namn, en stjärna inbyggd i projektets identitet. Naturliga jästsvampar, inga tillsatser, minimal intervention i källaren."}$j$::jsonb;

