-- wines.winemaker_notes — Zeph
UPDATE public.wines
SET winemaker_notes = $j${"en": "Pierre Regnault, Pierre et l'Étoile, Assignan, 270m. Founded 2017, organic since 2017, no added sulphites since 2020. Zeph takes its name from Zéphyr — the gentle westerly wind. Early harvest is a deliberate strategy to keep alcohol low and freshness high.", "sv": "Pierre Regnault, Pierre et l'Étoile, Assignan, 270m. Grundat 2017, ekologisk sedan 2017, inga tillsatta sulfiter sedan 2020. Zeph heter sitt namn från Zéphyr — den milda västliga vinden. Tidig skörd är en medveten strategi för att hålla alkoholen låg och friskheteten hög."}$j$::jsonb
