  AND winemaker_notes = $j${"en": "Pierre Regnault, Pierre et l'Étoile, Assignan, 270m. Founded 2017, organic since 2020, no added sulphites since 2020. Zeph takes its name from Zéphyr — the gentle westerly wind. Early harvest is a deliberate strategy to keep alcohol low and freshness high.", "sv": "Pierre Regnault, Pierre et l'Étoile, Assignan, 270m. Grundat 2017, ekologisk sedan 2020, inga tillsatta sulfiter sedan 2020. Zeph heter sitt namn från Zéphyr — den milda västliga vinden. Tidig skörd är en medveten strategi för att hålla alkoholen låg och friskheteten hög."}$j$::jsonb;

-- ---------------------------------------------------------------------------
-- 4) Mas Des Mesures + Peira Levada — clear wine-level biodynamic_certified
--    No uncertified 'biodynamic' farming enum value (CHECK + app catalog);
--    set farming to NULL rather than inventing a new value.
-- ---------------------------------------------------------------------------
UPDATE public.wines AS w
SET farming = NULL
FROM public.producers AS p
WHERE w.producer_id = p.id
  AND p.name IN ('Mas Des Mesures', 'Peira Levada')
  AND w.farming = 'biodynamic_certified';
